begin;
create extension if not exists pgtap with schema extensions;
select plan(14);
insert into auth.users(id,email,email_confirmed_at,created_at,updated_at) values ('11000000-1000-0000-0000-000000000001','incident-admin@example.test',now(),now(),now()),('11000000-1000-0000-0000-000000000002','incident-owner@example.test',now(),now(),now());
insert into public.app_users(id,is_platform_admin) values ('11000000-1000-0000-0000-000000000001',true),('11000000-1000-0000-0000-000000000002',false);
insert into public.players(id,name,display_name,email,user_id,auth_user_id) values ('21000000-1000-0000-0000-000000000001','Incident owner','Incident owner','incident-owner@example.test','11000000-1000-0000-0000-000000000002','11000000-1000-0000-0000-000000000002');
insert into public.teams(id,name,join_code,created_by) values ('31000000-1000-0000-0000-000000000001','Incident Team','INCI0001','21000000-1000-0000-0000-000000000001');
insert into public.billing_customers(id,owner_user_id,customer_type,team_id,billing_name,billing_email) values ('41000000-1000-0000-0000-000000000001','11000000-1000-0000-0000-000000000002','team','31000000-1000-0000-0000-000000000001','Incident payer','incident-owner@example.test');
insert into public.commercial_subscriptions(id,billing_customer_id,offering_id,price_version_id,team_id,provider,provider_subscription_id,state,current_period_start,current_period_end)
select '51000000-1000-0000-0000-000000000001','41000000-1000-0000-0000-000000000001',o.id,p.id,'31000000-1000-0000-0000-000000000001','stripe','sub_incident_test','active',now(),now()+interval '90 days' from public.commercial_offerings o join public.commercial_price_versions p on p.offering_id=o.id where o.code='team-season-standard' and o.state='published' and p.state='published' limit 1;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"11000000-1000-0000-0000-000000000002","role":"authenticated"}',true);
select is(public.get_incident_admin_queue(),null,'normal users cannot inspect the incident administration queue');
select throws_ok($$select public.create_service_incident('Payments unavailable','critical','Payments cannot currently be completed.',array['payments'],'Unauthorised incident')$$,'P0001','Incident administrator access required','normal users cannot create incidents');
select set_config('request.jwt.claims','{"sub":"11000000-1000-0000-0000-000000000001","role":"authenticated"}',true);
select lives_ok($$select public.create_service_incident('Payments unavailable','critical','Payments cannot currently be completed.',array['payments','data'],'Critical payment incident drill')$$,'admin creates a component-scoped material incident');
select set_config('test.incident_id',(public.get_incident_admin_queue()->0->>'id'),true);
select is(jsonb_array_length(public.get_incident_admin_queue()),1,'admin can inspect the unresolved incident queue');
reset role;
select is((select count(*)::integer from public.service_incident_updates where incident_id=current_setting('test.incident_id')::uuid),1,'initial public incident update is recorded');
select is((select count(*)::integer from public.commercial_notification_deliveries where notification_type='service_incident'),1,'material incident queues one notice per affected active billing customer');
select is((select payload->>'impact' from public.commercial_notification_deliveries where notification_type='service_incident'),'critical','queued incident notice contains safe public impact data');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"11000000-1000-0000-0000-000000000001","role":"authenticated"}',true);
select lives_ok($sql$select public.update_service_incident(current_setting('test.incident_id')::uuid,'identified','Payment provider connectivity has been identified.','Traffic isolated while recovery is tested.','{}',true,'Publish identified incident update')$sql$,'admin publishes mitigation progress');
select throws_ok($sql$select public.update_service_incident(current_setting('test.incident_id')::uuid,'resolved','Payments have returned to normal.','Fixed','{}',true,'Incomplete resolution')$sql$,'P0001','Resolution requires mitigation and tracked post-incident actions','resolution requires mitigation and follow-up actions');
select is((public.update_service_incident(current_setting('test.incident_id')::uuid,'resolved','Payments have returned to normal.','Provider connectivity recovered and verified.',array['Review provider failover','Complete incident retrospective'],true,'Resolve payment incident')->>'status'),'resolved','admin resolves with mitigation and post-incident actions');
reset role;
select is((select count(*)::integer from public.service_incident_updates where incident_id=current_setting('test.incident_id')::uuid),3,'incident timeline records investigation, mitigation and resolution');
select is((select count(*)::integer from public.commercial_notification_deliveries where notification_type='service_incident'),3,'each material public update queues one deduplicated customer notice');
select is((select count(*)::integer from public.commercial_audit_log where entity_type='service_incident' and entity_id=current_setting('test.incident_id')),3,'incident creation and updates are audited');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"11000000-1000-0000-0000-000000000001","role":"authenticated"}',true);
select throws_ok($sql$select public.update_service_incident(current_setting('test.incident_id')::uuid,'monitoring','Attempt to reopen a resolved incident.','No change',array['None'],false,'Reopen test')$sql$,'P0001','Resolved incidents are immutable','resolved incident cannot be silently reopened');
select * from finish();
rollback;
